-- HELPERS
function Data.EnsureDB()
    DeathLoggerDB = DeathLoggerDB or {}
    if DeathLoggerDB.showDeathMap == nil then
        DeathLoggerDB.showDeathMap = true
    end
    if DeathLoggerDB.showCSVMap == nil then
        DeathLoggerDB.showCSVMap = false
    end
end

function Data.NormalizeZone(name)
    if not name or type(name) ~= "string" then return "" end
    name = name:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")
    name = name:gsub("%s*%(?[%d%.]+%s*[,/]%s*[%d%.]+%)?%s*$", "")
    name = name:match("^%s*(.-)%s*$") or name
    name = strlower(name)
    return Data.ZONE_ALIASES[name] or name
end

function Data.NormalizeName(name)
    if not name or type(name) ~= "string" then return "" end
    name = name:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")
    name = name:gsub("%s*%(Ур%.?%s*%d+%)%s*$", "")
    name = name:gsub("%s*%(Level%s*%d+%)%s*$", "")
    name = name:match("^%s*(.-)%s*$") or name
    return strlower(name)
end

function Data.ParseLocationFromTooltip(tooltip)
    if not tooltip or type(tooltip) ~= "string" then return nil end
    local loc = tooltip:match("Локация:%s*([^\n]+)")
    if loc then
        loc = loc:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")
        return loc:match("^%s*(.-)%s*$")
    end
    return nil
end

function Data.TryParseCoords(str)
    if not str or type(str) ~= "string" then return nil, nil end
    str = str:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")
    local a, b = str:match("(%d+[%.,]?%d*)%s*[/,]%s*(%d+[%.,]?%d*)")
    if not a or not b then return nil, nil end
    a = tonumber((a:gsub(",", ".")))
    b = tonumber((b:gsub(",", ".")))
    if not a or not b then return nil, nil end
    if a > 1.5 or b > 1.5 then
        a = a / 100
        b = b / 100
    end
    if a < 0 or a > 1 or b < 0 or b > 1 then
        return nil, nil
    end
    return a, b
end
